/* From Uiverse.io by Saiyed-Tanvir - Tags: loader, animated, circle loader, circular */
.__UIV_SCOPE__ .quater {
  height: 1.5cm;
  width: 1.5cm;
  background-color: skyblue;
  float: left;
  position: relative;
  bottom: 1.25cm;
}

.__UIV_SCOPE__ .i {
  border-top-left-radius: 100%;
  animation: spin1 2s ease-in-out infinite;
  transform-origin: 1.5cm 1.5cm;
}

.__UIV_SCOPE__ .ii {
  border-top-right-radius: 100%;
  animation: spin2 2s ease-in-out infinite;
  transform-origin: 0 1.5cm;
}

@keyframes spin1 {
  0% {
    transform: rotateZ(0deg);
  }

  25% {
    transform: rotateZ(0deg);
  }

  50% {
    transform: rotateZ(180deg);
  }

  75% {
    transform: rotateZ(180deg);
  }

  100% {
    transform: rotateZ(360deg);
  }
}

@keyframes spin2 {
  0% {
    transform: rotateZ(0deg);
  }

  25% {
    transform: rotateZ(180deg);
  }

  50% {
    transform: rotateZ(180deg);
  }

  75% {
    transform: rotateZ(360deg);
  }

  100% {
    transform: rotateZ(360deg);
  }
}
